    };

    private RenderFragment RenderSecurity() => __builder =>
    {
        <h4 class="section-title">Security</h4>

        <!-- Change Password -->
        <div class="expandable-panel">
            <button class="panel-header" @onclick="() => _changePasswordExpanded = !_changePasswordExpanded">
                <span>🔑 Change Password</span>
                <span class="expand-icon">@(_changePasswordExpanded ? "▲" : "▼")</span>
            </button>
            @if (_changePasswordExpanded)
            {
                <div class="panel-body">
                    <div class="mb-2">
                        <label class="form-label">Current Password</label>
                        <input type="password" class="form-control form-control-sm" @bind="_currentPassword" />
                    </div>
                    <div class="mb-2">
                        <label class="form-label">New Password</label>
                        <input type="password" class="form-control form-control-sm" @bind="_newPassword" />
                    </div>
                    <div class="mb-2">
                        <label class="form-label">Confirm New Password</label>
                        <input type="password" class="form-control form-control-sm" @bind="_confirmPassword" />
                    </div>
                    <button class="btn btn-warning btn-sm" @onclick="ChangePassword">Update Password</button>
                </div>
            }
        </div>

        @if (_security?.LastPasswordChange is not null)
        {
            <p class="text-muted small mt-1">Last changed: @_security.LastPasswordChange.Value.ToString("MMMM dd, yyyy")</p>
        }

        <!-- Two-Factor Authentication -->
        <div class="toggle-row mt-3">
            <div>
                <span>Two-Factor Authentication</span>
                <span class="status-badge @(_twoFactorEnabled ? "status-on" : "status-off")">
                    @(_twoFactorEnabled ? "Enabled" : "Disabled")
                </span>
            </div>
            <label class="toggle-switch">
                <input type="checkbox" @bind="_twoFactorEnabled" />
                <span class="toggle-slider"></span>
            </label>
        </div>

        <!-- Active Sessions -->
        <h6 class="mt-4 mb-2">Active Sessions</h6>
        @if (_security?.Sessions is { Count: > 0 })
        {
            <div class="table-responsive">
                <table class="table table-sm table-hover">
                    <thead>
                        <tr>
                            <th>Device</th>
                            <th>Location</th>
                            <th>Last Active</th>
                            <th></th>
                        </tr>
                    </thead>
                    <tbody>
                        @foreach (var session in _security.Sessions)
                        {
                            var isCurrent = session == _security.Sessions[0];
                            <tr>
                                <td>@session.Device</td>
                                <td>@session.Location</td>
                                <td>@FormatLastActive(session.LastActive)</td>
                                <td>
                                    @if (isCurrent)
                                    {
                                        <span class="badge bg-success">Current</span>
                                    }
                                    else
                                    {
                                        <button class="btn btn-outline-danger btn-sm"
                                                @onclick="() => PromptRevokeSession(session)">Revoke</button>
                                    }
                                </td>
                            </tr>
                        }
                    </tbody>
                </table>
            </div>
        }
    };

    private static string FormatLastActive(DateTime dt)
    {
        var diff = DateTime.UtcNow - dt;
        if (diff.TotalMinutes < 1) return "Just now";
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes}m ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours}h ago";
        return $"{(int)diff.TotalDays}d ago";
    }

    private RenderFragment RenderAppearance() => __builder =>
    {
        <h4 class="section-title">Appearance</h4>

        <!-- Theme -->
        <div class="mb-3">
            <label class="form-label fw-semibold">Theme</label>
            <div class="d-flex gap-3">
                @foreach (var t in _themes)
                {
                    <label class="radio-option">
                        <input type="radio" name="theme" value="@t"
                               checked="@(_theme == t)"
                               @onchange="() => _theme = t" />
                        @t
                    </label>
                }
            </div>
        </div>

        <!-- Font Size -->
        <div class="mb-3">
            <label class="form-label fw-semibold">Font Size</label>
            <div class="d-flex gap-3">
                @foreach (var fs in _fontSizes)
                {
                    <label class="radio-option">
                        <input type="radio" name="fontSize" value="@fs"
                               checked="@(_fontSize == fs)"
                               @onchange="() => _fontSize = fs" />
                        @fs
                    </label>
                }
            </div>
        </div>

        <!-- Language -->
        <div class="mb-3">
            <label class="form-label fw-semibold">Language</label>
            <select class="form-select" @bind="_language">
                @foreach (var lang in _languages)
                {
                    <option value="@lang">@lang</option>
                }
            </select>
        </div>

        <!-- Compact Mode -->
        <div class="toggle-row mb-3">
            <span>Compact Mode</span>
            <label class="toggle-switch">
                <input type="checkbox" @bind="_compactMode" />
                <span class="toggle-slider"></span>
            </label>
        </div>

        <!-- Live Preview -->
        <div class="preview-area @GetPreviewClasses()">
            <h6 class="preview-title">Live Preview</h6>
            <p class="preview-text">This is how your content will look with the current settings.</p>
            <div class="d-flex gap-2">
                <button class="btn btn-sm @(_theme == "Dark" ? "btn-light" : "btn-dark")">Sample Button</button>
                <span class="badge @(_theme == "Dark" ? "bg-light text-dark" : "bg-dark")">Badge</span>
            </div>
        </div>

        <button class="btn btn-primary mt-3" @onclick="SaveAppearance">Save</button>
    };

    private string GetPreviewClasses()
    {
        var classes = new List<string>();
        classes.Add(_theme switch
        {
            "Dark" => "preview-dark",
            "System" => "preview-system",
            _ => "preview-light"
        });
        classes.Add(_fontSize switch
        {
            "Small" => "preview-font-sm",
            "Large" => "preview-font-lg",
            _ => "preview-font-md"
        });
        if (_compactMode) classes.Add("preview-compact");
        return string.Join(' ', classes);
    }
}

